1	import { FlashList, type FlashListRef } from "@shopify/flash-list";
2	import type { RoomInterface } from "@unomed/react-native-matrix-sdk";
3	import { TimelineItemContent_Tags } from "@unomed/react-native-matrix-sdk";
4	import { useAtom, useSetAtom } from "jotai";
5	import {
6	  addDateDividers,
7	  getEventId,
8	  getItemUniqueKey,
9	  groupInfoEvents,
10	} from "modules/matrix-client/utils";
11	import { useRoomIdentityViolations } from "modules/room/hooks";
12	import { useRoomTimeline } from "modules/timeline/hooks";
13	import { TimelineAtoms } from "modules/timeline/jotai";
14	import { filterSameStateKey } from "modules/timeline/utils";
15	import {
16	  type FC,
17	  useCallback,
18	  useEffect,
19	  useMemo,
20	  useRef,
21	  useState,
22	} from "react";
23	import {
24	  KeyboardAvoidingView,
25	  type NativeScrollEvent,
26	  type NativeSyntheticEvent,
27	  StyleSheet,
28	} from "react-native";
29	import { useMediaTimeline } from "screens/room-media/hooks";
30	import { MemberDetailsBottomSheet, SeenByBottomSheet } from "shared/components";
31	import { useMemberDetails } from "shared/hooks";
32	import { DateDivider } from "../date-divider";
33	import { FailedEchoBottomSheet } from "../failed-echo-bottom-sheet";
34	import { GroupedInfoMessages } from "../grouped-info-messages";
35	import { MessageContentBottomSheet } from "../message-content-bottom-sheet";
36	import { NewMessagesButton } from "../new-messages-button";
37	import { ReactionsBottomSheet } from "../reactions-bottom-sheet";
38	import { RoomIdentityBanner } from "../room-identity-banner";
39	import { RoomInput } from "../room-input";
40	import { ScrollToBottomButton } from "../scroll-to-bottom-button";
41	import { ShieldModal } from "../shield-modal";
42	import { SingleMessageType } from "../single-message-type";
43	
44	interface Props {
45	  room: RoomInterface;
46	  roomId: string;
47	}
48	
49	export const RoomTimeline: FC<Props> = ({ room, roomId }) => {
50	  const flashListRef = useRef<FlashListRef<TimelineListItem>>(null);
51	  const isAtBottomRef = useRef(true);
52	  const suppressScrollDownRef = useRef(false);
53	  const lastEventKeyRef = useRef<string | undefined>(undefined);
54	  const visibleHeightRef = useRef(0);
55	  const [showNewMessageArrived, setShowNewMessageArrived] = useState(false);
56	  const [showScrollDown, setShowScrollDown] = useState(false);
57	  const {
58	    events,
59	    isPaginatingRef,
60	    reachedStartRef,
61	    isDirect,
62	    loadMoreMessages,
63	    markAsRead,
64	  } = useRoomTimeline({
65	    room,
66	    roomId,
67	  });
68	  const { mediaItems } = useMediaTimeline({ room, roomId });
69	  const [scrollToEventId, setScrollToEventId] = useAtom(
70	    TimelineAtoms.scrollToEventId,
71	  );
72	  const [seenByUsers, setSeenByUsers] = useAtom(TimelineAtoms.seenByUsers);
73	  const [reactionsPayload, setReactionsPayload] = useAtom(
74	    TimelineAtoms.reactionsPayload,
75	  );
76	  const [shieldPayload, setShieldPayload] = useAtom(
77	    TimelineAtoms.shieldPayload,
78	  );
79	  const { isPinViolatingUsersLoading, violatingUsers, pinViolatingUsers } =
80	    useRoomIdentityViolations(room);
81	  const {
82	    selectedMember,
83	    isBottomSheetOpen,
84	    openMemberDetails,
85	    closeMemberDetails,
86	  } = useMemberDetails();
87	  const setRoomMediaItems = useSetAtom(TimelineAtoms.roomMediaItems);
88	
89	  const sortedEvents = useMemo(() => {
90	    const sorted = [...events].sort(
91	      (a, b) => Number(a.timestamp) - Number(b.timestamp),
92	    );
93	
94	    return filterSameStateKey(sorted);
95	  }, [events]);
96	
97	  const eventsWithDividers = useMemo(() => {
98	    const items = groupInfoEvents(addDateDividers(sortedEvents));
99	
100	    // Pre-compute isPreviousSameSender so it's not recalculated per-item during render
101	    let prevSender: string | null = null;
102	    for (const item of items) {
103	      if (item.type !== "event") {
104	        prevSender = null;
105	        continue;
106	      }
107	      const isMsgLike =
108	        item.data.content.tag === TimelineItemContent_Tags.MsgLike;
109	      if (!isMsgLike) {
110	        prevSender = null;
111	        continue;
112	      }
113	      item.isPreviousSameSender =
114	        isDirect || (prevSender !== null && prevSender === item.data.sender);
115	      prevSender = item.data.sender;
116	    }
117	
118	    return items;
119	  }, [sortedEvents, isDirect]);
120	
121	  // Reverse for inverted FlashList: [newest, ..., oldest]
122	  const reversedEvents = useMemo(
123	    () => [...eventsWithDividers].reverse(),
124	    [eventsWithDividers],
125	  );
126	
127	  const handleScrollToEvent = useCallback(
128	    (eventId: string) => {
129	      const index = reversedEvents.findIndex(
130	        (item) => item.type === "event" && getEventId(item.data) === eventId,
131	      );
132	      if (index === -1) return;
133	
134	      flashListRef.current?.scrollToIndex({
135	        index,
136	        animated: true,
137	        viewPosition: 0.5,
138	      });
139	    },
140	    [reversedEvents],
141	  );
142	
143	  useEffect(() => {
144	    setRoomMediaItems(mediaItems);
145	  }, [mediaItems, setRoomMediaItems]);
146	
147	  useEffect(() => {
148	    return () => setRoomMediaItems([]);
149	  }, [setRoomMediaItems]);
150	
151	  useEffect(() => {
152	    if (!scrollToEventId) return;
153	    handleScrollToEvent(scrollToEventId);
154	    setScrollToEventId(null);
155	  }, [scrollToEventId, handleScrollToEvent, setScrollToEventId]);
156	
157	  const handleScrollDown = useCallback(() => {
158	    // In inverted list, offset 0 is the visual bottom (newest messages)
159	    suppressScrollDownRef.current = true;
160	    flashListRef.current?.scrollToOffset({ offset: 0, animated: true });
161	    setShowNewMessageArrived(false);
162	    setShowScrollDown(false);
163	  }, []);
164	
165	  const handleOnScroll = useCallback(
166	    ({ nativeEvent }: NativeSyntheticEvent<NativeScrollEvent>) => {
167	      const { layoutMeasurement, contentOffset, contentSize } = nativeEvent;
168	      visibleHeightRef.current = layoutMeasurement.height;
169	
170	      // Inverted list: large contentOffset.y = near oldest messages (visual top)
171	      // Paginate when within 2x visible height of the oldest content
172	      const distanceFromTop =
173	        contentSize.height - contentOffset.y - layoutMeasurement.height;
174	      const nearTop = distanceFromTop < layoutMeasurement.height * 2;
175	      if (nearTop && !isPaginatingRef.current && !reachedStartRef.current) {
176	        loadMoreMessages();
177	      }
178	
179	      // Inverted list: contentOffset.y near 0 = at visual bottom (newest messages)
180	      const paddingToBottom = 100;
181	      const atBottom = contentOffset.y <= paddingToBottom;
182	      isAtBottomRef.current = atBottom;
183	
184	      if (!suppressScrollDownRef.current) setShowScrollDown(!atBottom);
185	
186	      if (!atBottom) return;
187	      suppressScrollDownRef.current = false;
188	      setShowNewMessageArrived(false);
189	      markAsRead();
190	    },
191	    [loadMoreMessages, markAsRead],
192	  );
193	
194	  const handleContentSizeChange = useCallback(
195	    (_w: number, contentHeight: number) => {
196	      // Auto-paginate if content doesn't fill the viewport (initial fill)
197	      if (
198	        contentHeight > 0 &&
199	        visibleHeightRef.current > 0 &&
200	        contentHeight < visibleHeightRef.current &&
201	        !isPaginatingRef.current &&
202	        !reachedStartRef.current
203	      ) {
204	        loadMoreMessages();
205	      }
206	    },
207	    [loadMoreMessages],
208	  );
209	
210	  // Unified new-message handler: scroll to bottom or show "new messages" button
211	  useEffect(() => {
212	    const lastEvent = sortedEvents[sortedEvents.length - 1];
213	    const lastEventKey = lastEvent
214	      ? (getItemUniqueKey(lastEvent) ?? undefined)
215	      : undefined;
216	    const isNewEvent = lastEventKey !== lastEventKeyRef.current;
217	    lastEventKeyRef.current = lastEventKey;
218	
219	    if (!isNewEvent) return;
220	
221	    if (lastEvent?.isOwn || isAtBottomRef.current) {
222	      // Scroll to bottom for own messages or when already at bottom
223	      flashListRef.current?.scrollToOffset({ offset: 0, animated: true });
224	      setShowNewMessageArrived(false);
225	    } else setShowNewMessageArrived(true);
226	  }, [sortedEvents]);
227	
228	  const renderItem = useCallback(
229	    ({ item }: { item: TimelineListItem }) => {
230	      if (item.type === "divider") {
231	        return <DateDivider date={item.date} />;
232	      }
233	
234	      if (item.type === "group") {
235	        return <GroupedInfoMessages events={item.events} roomId={roomId} />;
236	      }
237	
238	      return (
239	        <SingleMessageType
240	          roomId={roomId}
241	          event={item.data}
242	          isPreviousSameSender={item.isPreviousSameSender}
243	          onMemberPress={openMemberDetails}
244	        />
245	      );
246	    },
247	    [roomId, openMemberDetails],
248	  );
249	
250	  const keyExtractor = useCallback((item: TimelineListItem) => {
251	    if (item.type === "divider") return item.id;
252	    if (item.type === "group") return item.id;
253	
254	    return getItemUniqueKey(item.data) ?? "";
255	  }, []);
256	
257	  useEffect(() => {
258	    return () => {
259	      setReactionsPayload(null);
260	      setSeenByUsers(null);
261	      setScrollToEventId(null);
262	      setShieldPayload(null);
263	    };
264	  }, []);
265	
266	  return (
267	    <>
268	      <KeyboardAvoidingView style={styles.flex} behavior="padding">
269	        {!!violatingUsers.length && (
270	          <RoomIdentityBanner
271	            users={violatingUsers}
272	            isLoading={isPinViolatingUsersLoading}
273	            onDismiss={pinViolatingUsers}
274	          />
275	        )}
276	        <FlashList
277	          ref={flashListRef}
278	          data={reversedEvents}
279	          inverted
280	          keyExtractor={keyExtractor}
281	          contentContainerStyle={styles.listContent}
282	          onContentSizeChange={handleContentSizeChange}
283	          onScroll={handleOnScroll}
284	          renderItem={renderItem}
285	        />
286	
287	        <RoomInput roomId={roomId} />
288	      </KeyboardAvoidingView>
289	
290	      <MessageContentBottomSheet roomId={roomId} />
291	
292	      <FailedEchoBottomSheet />
293	
294	      <MemberDetailsBottomSheet
295	        isBottomSheetOpen={isBottomSheetOpen}
296	        selectedMember={selectedMember}
297	        roomId={roomId}
298	        onClose={closeMemberDetails}
299	      />
300	
301	      <NewMessagesButton
302	        visible={showNewMessageArrived}
303	        onPress={handleScrollDown}
304	      />
305	
306	      <ScrollToBottomButton
307	        visible={showScrollDown && !showNewMessageArrived}
308	        onPress={handleScrollDown}
309	      />
310	
311	      <SeenByBottomSheet
312	        isOpen={!!seenByUsers}
313	        users={seenByUsers ?? []}
314	        onClose={() => setSeenByUsers(null)}
315	      />
316	
317	      <ReactionsBottomSheet
318	        isOpen={!!reactionsPayload}
319	        reactions={reactionsPayload ?? []}
320	        onClose={() => setReactionsPayload(null)}
321	      />
322	
323	      <ShieldModal
324	        visible={!!shieldPayload}
325	        onClose={() => setShieldPayload(null)}
326	        isRed={shieldPayload?.isRed ?? false}
327	        message={shieldPayload?.message ?? ""}
328	      />
329	    </>
330	  );
331	};
332	
333	const styles = StyleSheet.create({
334	  flex: {
335	    flex: 1,
336	  },
337	  listContent: {
338	    paddingHorizontal: 20,
339	    paddingTop: 20,
340	    paddingBottom: 12,
341	  },
342	});
343

