import { useCallback, useEffect, useRef, useState } from "react";

interface UseMediaTimelineProps {
  room: RoomInterface | undefined;
  roomId: string;
}

const PAGE_SIZE = 10;
// How many raw events to fetch per paginateBackwards call. Matrix filters
// media post-fetch, so we overshoot to improve the chance each call yields
// at least PAGE_SIZE media items before bailing out.
const RAW_FETCH_SIZE = 40;

export const useMediaTimeline = ({ room, roomId }: UseMediaTimelineProps) => {
  const [mediaItems, setMediaItems] = useState<EventTimelineItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const [reachedEnd, setReachedEnd] = useState(false);
  const eventIdsRef = useRef<Set<string>>(new Set());
  const timelineRef = useRef<TimelineInterface | null>(null);
  const isPaginatingRef = useRef(false);
  const reachedEndRef = useRef(false);

