    setMediaItems((prev) => {
      const next = [...prev];
      for (const event of incoming) {
        const id = getEventId(event);
        if (!id || eventIdsRef.current.has(id)) continue;

        eventIdsRef.current.add(id);
        next.push(event);
      }
      return next.sort((a, b) => Number(b.timestamp) - Number(a.timestamp));
    });
  }, []);

  const paginateUntilPageFilled = useCallback(async () => {
    const timeline = timelineRef.current;
    if (!timeline) return;
    const startCount = eventIdsRef.current.size;
    while (!reachedEndRef.current) {
      const hitStart = await timeline.paginateBackwards(RAW_FETCH_SIZE);
      if (hitStart) {
        reachedEndRef.current = true;
        setReachedEnd(true);
        break;
      }
      // Give the timeline listener a tick to apply diffs to eventIdsRef.
      await new Promise((resolve) => setTimeout(resolve, 0));
      const added = eventIdsRef.current.size - startCount;
      if (added >= PAGE_SIZE) break;
    }
  }, []);

