    if (isPaginatingRef.current || reachedEndRef.current) return;
    if (!timelineRef.current) return;
    isPaginatingRef.current = true;
    setIsLoadingMore(true);
    try {
      await paginateUntilPageFilled();
    } catch (error) {
      console.error("Failed to paginate media timeline:", error);
    } finally {
      setIsLoadingMore(false);
      isPaginatingRef.current = false;
    }
  }, [paginateUntilPageFilled]);

  useEffect(() => {
    if (!room) return;

    setLoading(true);
    setIsLoadingMore(false);
    setReachedEnd(false);
    setMediaItems([]);
    eventIdsRef.current.clear();
    reachedEndRef.current = false;
    isPaginatingRef.current = false;

    let timelineListenerHandle: TaskHandleInterface | null = null;
    let isDisposed = false;

