                  }
                  break;
                }
                case TimelineDiff_Tags.Clear: {
                  eventIdsRef.current.clear();
                  setMediaItems([]);
                  break;
                }
                default:
                  break;
              }
            });
          },
        });

        if (isDisposed) return;

        // Load the initial page only; no more aggressive full-history loop.
        isPaginatingRef.current = true;
        try {
          await paginateUntilPageFilled();
        } finally {
          isPaginatingRef.current = false;
        }
        if (!isDisposed) setLoading(false);
      } catch (error) {
        console.error("Failed to initialize media timeline:", error);
        if (!isDisposed) setLoading(false);
      }
    };

    initMediaTimeline();

    return () => {
      isDisposed = true;
      timelineListenerHandle?.cancel?.();
      timelineRef.current = null;
      isPaginatingRef.current = false;
      reachedEndRef.current = false;
    };
  }, [roomId, room, upsertMediaItems, paginateUntilPageFilled]);

  return {
    mediaItems,
    loading,
    isLoadingMore,
    reachedEnd,
    loadMore,
  };
};

