import { BottomSheetModalProvider } from "@gorhom/bottom-sheet";
import { FlashList, type FlashListRef } from "@shopify/flash-list";
import { animateParallel, Block, Text } from "@prototyp/skeletor";
import {
  type EventTimelineItem,
  ProfileDetails_Tags,
} from "@unomed/react-native-matrix-sdk";
import { format } from "date-fns";
import { useAtom, useAtomValue, useSetAtom } from "jotai";
import { getEventId } from "modules/matrix-client/utils";
import { TimelineAtoms } from "modules/timeline/jotai";
import {
  type FC,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { Dimensions, Image, Modal, StyleSheet, View } from "react-native";
import { ImageInfoBottomSheet } from "screens/room/fragments/image-info-bottom-sheet";
import { VideoInfoBottomSheet } from "screens/room/fragments/video-info-bottom-sheet";
import { Colors, TextSize } from "shared/styles";
import { BlurGradientOverlay } from "../blur-gradient-overlay";
import { Button } from "../button";
import { Loading } from "../loading";
import { MediaImagePage } from "./MediaImagePage";
import { MediaVideoPage } from "./MediaVideoPage";
import { getMediaKind } from "./utils";

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get("window");

const VIEWABILITY_CONFIG = { itemVisiblePercentThreshold: 80 };
const LOADER_KEY = "__media_viewer_loader__";

type ViewerItem =
  | { type: "event"; event: EventTimelineItem; key: string }
  | { type: "loader"; key: typeof LOADER_KEY };

export const MediaViewerModal: FC = () => {
  const [payload, setPayload] = useAtom(TimelineAtoms.mediaViewerPayload);
  const store = useAtomValue(TimelineAtoms.mediaTimelineStore);
  const setImageInfoPayload = useSetAtom(TimelineAtoms.imageInfoPayload);
  const setVideoInfoPayload = useSetAtom(TimelineAtoms.videoInfoPayload);
  const listRef = useRef<FlashListRef<ViewerItem>>(null);
  const [showControls, setShowControls] = useState(true);
  const [currentIndex, setCurrentIndex] = useState(0);
  const localUriByEventIdRef = useRef<Map<string, string | null>>(new Map());
  const currentEventIdRef = useRef<string | null>(null);
  const prevLengthRef = useRef(0);
  const storeRef = useRef(store);
  storeRef.current = store;

  const visible = !!payload;
  const roomId = payload?.roomId ?? null;

  // Use live store when it matches the payload's room; otherwise the payload
  // is the only source (e.g. tapping a single image from chat).
  const isStoreLive = !!store && !!payload && store.roomId === payload.roomId;

  const displayItems = useMemo<ViewerItem[]>(() => {
    if (!payload) return [];
    const source = isStoreLive && store ? store.items : payload.items;
    const filtered = source.filter((item) => getMediaKind(item) !== null);
    // Source is newest-first; reverse so newest sits on the right edge
    // and swiping right reveals older media.
    const reversed = [...filtered].reverse();
    const list: ViewerItem[] = reversed.map((event) => ({
      type: "event",
      event,
      key: getEventId(event) ?? `${event.timestamp}`,
    }));
    if (isStoreLive && store && !store.reachedEnd) {
      list.unshift({ type: "loader", key: LOADER_KEY });
    }
    return list;
  }, [payload, isStoreLive, store]);

  const initialIndex = useMemo(() => {
    if (!payload) return 0;
    const idx = displayItems.findIndex(
      (item) =>
        item.type === "event" && getEventId(item.event) === payload.initialEventId,
    );
    return idx >= 0 ? idx : 0;
  }, [displayItems, payload]);

  useEffect(() => {
    if (!visible) return;
    setCurrentIndex(initialIndex);
    const initialItem = displayItems[initialIndex];
    if (initialItem?.type === "event") {
      currentEventIdRef.current = getEventId(initialItem.event) ?? null;
    }
    prevLengthRef.current = displayItems.length;
  }, [visible, initialIndex]);

  useEffect(() => {
    if (!visible || initialIndex === 0) return;
    const id = setTimeout(() => {
      listRef.current?.scrollToIndex({
        index: initialIndex,
        animated: false,
      });
    }, 0);
    return () => clearTimeout(id);
  }, [visible, initialIndex]);

  // After pagination extends the list, keep the user anchored on the event
  // they were viewing. New older items are prepended, so indices shift.
  useEffect(() => {
    if (!visible) return;
    const prev = prevLengthRef.current;
    const next = displayItems.length;
    if (next === prev) return;
    prevLengthRef.current = next;
    const eventId = currentEventIdRef.current;
    if (!eventId) return;
    const newIndex = displayItems.findIndex(
      (item) => item.type === "event" && getEventId(item.event) === eventId,
    );
    if (newIndex < 0 || newIndex === currentIndex) return;
    listRef.current?.scrollToIndex({ index: newIndex, animated: false });
    setCurrentIndex(newIndex);
  }, [displayItems, visible, currentIndex]);

  const currentViewerItem = displayItems[currentIndex];
  const currentItem =
    currentViewerItem?.type === "event" ? currentViewerItem.event : null;
  const currentKind = currentItem ? getMediaKind(currentItem) : null;

  const senderName = useMemo(() => {
    if (!currentItem) return null;
    if (currentItem.senderProfile.tag === ProfileDetails_Tags.Ready) {
      return (
        currentItem.senderProfile.inner.displayName ?? currentItem.sender
      );
    }
    return currentItem.sender;
  }, [currentItem]);

  const formattedDate = useMemo(() => {
    if (!currentItem) return null;
    return format(Number(currentItem.timestamp), "MMM d, HH:mm");
  }, [currentItem]);

  const controlsAnimation = useRef(
    animateParallel(
      { translateY: [-120, 0], opacity: [0, 1] },
      { duration: 280 },
    ),
  ).current;

  useEffect(() => {
    if (showControls) controlsAnimation.start();
    else controlsAnimation.reverse();
  }, [showControls]);

  const onClose = useCallback(() => {
    setPayload(null);
    setShowControls(true);
    setCurrentIndex(0);
    currentEventIdRef.current = null;
    prevLengthRef.current = 0;
    localUriByEventIdRef.current.clear();
  }, [setPayload]);

  const handleSingleTap = useCallback(() => {
    setShowControls((prev) => !prev);
  }, []);

  const handleViewableItemsChanged = useCallback(
    ({
      viewableItems,
    }: {
      viewableItems: { index: number | null; item?: ViewerItem }[];
    }) => {
      const first = viewableItems[0];
      if (first?.index == null) return;
      setCurrentIndex(first.index);
      const viewerItem = first.item;
      if (viewerItem?.type === "event") {
        currentEventIdRef.current = getEventId(viewerItem.event) ?? null;
      }
      if (viewerItem?.type === "loader") {
        const s = storeRef.current;
        if (s && !s.reachedEnd && !s.isLoadingMore) {
          s.loadMore();
        }
      }
    },
    [],
  );

  const handleLocalUriChange = useCallback(
    (eventId: string | null, uri: string | null) => {
      if (!eventId) return;
      localUriByEventIdRef.current.set(eventId, uri);
    },
    [],
  );

  const handleOpenInfo = useCallback(() => {
    if (!currentItem || !roomId) return;
    const eventId = getEventId(currentItem);
    const localUri = eventId
      ? localUriByEventIdRef.current.get(eventId) ?? null
      : null;
    if (currentKind === "image") {
      setImageInfoPayload({ event: currentItem, roomId, localUri });
    } else if (currentKind === "video") {
      setVideoInfoPayload({ event: currentItem, roomId, localUri });
    }
  }, [
    currentItem,
    currentKind,
    roomId,
    setImageInfoPayload,
    setVideoInfoPayload,
  ]);

  const keyExtractor = useCallback((item: ViewerItem) => item.key, []);

  const renderItem = useCallback(
    ({ item, index }: { item: ViewerItem; index: number }) => {
      if (item.type === "loader") {
        return (
          <View style={styles.page}>
            <View style={styles.loaderContainer}>
              <Loading isFullScreen={false} />
            </View>
          </View>
        );
      }
      const kind = getMediaKind(item.event);
      const eventId = getEventId(item.event);
      const onUriChange = (uri: string | null) =>
        handleLocalUriChange(eventId, uri);
      return (
        <View style={styles.page}>
          {kind === "image" ? (
            <MediaImagePage
              event={item.event}
              onSingleTap={handleSingleTap}
              onLocalUriChange={onUriChange}
            />
          ) : kind === "video" ? (
            <MediaVideoPage
              event={item.event}
              isActive={index === currentIndex}
              onSingleTap={handleSingleTap}
              onLocalUriChange={onUriChange}
            />
          ) : null}
        </View>
      );
    },
    [currentIndex, handleSingleTap, handleLocalUriChange],
  );

  if (!visible) return null;

  return (
    <Modal
      visible={visible}
      animationType="fade"
      statusBarTranslucent
      transparent
      onRequestClose={onClose}
    >
      <BottomSheetModalProvider>
        <Block background={Colors.black} flex={1}>
          <FlashList
            ref={listRef}
            data={displayItems}
            renderItem={renderItem}
            keyExtractor={keyExtractor}
            horizontal
            pagingEnabled
            showsHorizontalScrollIndicator={false}
            initialScrollIndex={initialIndex}
            onViewableItemsChanged={handleViewableItemsChanged}
            viewabilityConfig={VIEWABILITY_CONFIG}
          />

          <Block
            absolute
            offsets={{ top: 0, left: 0, right: 0 }}
            zIndex={10}
            paddings={[56, 20, 16, 20]}
            flexDirection="row"
            align="center"
            justify="space-between"
            gap={12}
            background={Colors.primary}
            animations={controlsAnimation.animations}
            pointerEvents={showControls ? "auto" : "none"}
          >
            <BlurGradientOverlay />
            <Block width={60} align="flex-start" zIndex={2}>
              {!!currentItem && (
                <Button.Wrapper onPress={handleOpenInfo}>
                  <Image
                    source={require("assets/icons/info.png")}
                    style={styles.infoIcon}
                    tintColor={Colors.white}
                  />
                </Button.Wrapper>
              )}
            </Block>
            <Block flex={1} align="center" gap={2} zIndex={2}>
              {senderName && (
                <Text
                  color={Colors.white}
                  font="InstrumentSans-Semibold"
                  numberOfLines={1}
                >
                  {senderName}
                </Text>
              )}
              {formattedDate && (
                <Text
                  size={TextSize.tiny}
                  color={Colors.white80}
                  numberOfLines={1}
                >
                  {formattedDate}
                </Text>
              )}
            </Block>
            <Block width={60} align="flex-end" zIndex={2}>
              <Button.Wrapper onPress={onClose}>
                <Text font="InstrumentSans-Semibold" color={Colors.white}>
                  Close
                </Text>
              </Button.Wrapper>
            </Block>
          </Block>
        </Block>
        <ImageInfoBottomSheet />
        <VideoInfoBottomSheet />
      </BottomSheetModalProvider>
    </Modal>
  );
};

const styles = StyleSheet.create({
  page: {
    width: SCREEN_WIDTH,
    height: SCREEN_HEIGHT,
  },
  loaderContainer: {
    flex: 1,
    alignItems: "center",
    justifyContent: "center",
  },
  infoIcon: {
    width: 24,
    height: 24,
  },
});

